#!/usr/bin/env bash
set -euo pipefail

echo "[MEMEFLOW] Installing approved loader V9"

ROOT="$(pwd)"
if [ -d "$ROOT/memeflow-app" ]; then
  APP="$ROOT/memeflow-app"
elif [ "$(basename "$ROOT")" = "memeflow-app" ]; then
  APP="$ROOT"
  ROOT="$(dirname "$ROOT")"
else
  echo "ERROR: memeflow-app not found. Run from ~/workspace or ~/workspace/memeflow-app"
  exit 1
fi

export APP
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$ROOT/.memeflow-loader-v9-backup-$STAMP"
mkdir -p "$BACKUP"

for f in system.html memeflow-brand.css; do
  [ -f "$APP/$f" ] && cp -p "$APP/$f" "$BACKUP/$f"
done

mkdir -p "$APP/brand/loader-v9"
echo "[MEMEFLOW] Backup: $BACKUP"

base64 -d > "$APP/brand/loader-v9/wing-upper-left.png" <<'MF_82C80500'

MF_82C80500

base64 -d > "$APP/brand/loader-v9/wing-upper-right.png" <<'MF_70ABF640'

MF_70ABF640

base64 -d > "$APP/brand/loader-v9/wing-lower-left.png" <<'MF_2701632B'

MF_2701632B

base64 -d > "$APP/brand/loader-v9/wing-lower-right.png" <<'MF_9FE92AE2'

MF_9FE92AE2

base64 -d > "$APP/brand/loader-v9/body.png" <<'MF_60984D66'

MF_60984D66

base64 -d > "$APP/brand/loader-v9/glow.png" <<'MF_71B1D7C0'

MF_71B1D7C0

python3 <<'PY'
import os, re
from pathlib import Path

app = Path(os.environ["APP"])
cssp = app / "memeflow-brand.css"
if not cssp.exists():
    raise SystemExit("ERROR: memeflow-brand.css not found")

css = cssp.read_text(encoding="utf-8")

# Remove previous loader-only blocks so this stays one clean final loader layer.
patterns = [
    r'/\* MEMEFLOW LOADER FINAL V7.*?(?=/\* MEMEFLOW LOADER FINAL|\Z)',
    r'/\* MEMEFLOW LOADER FINAL V9.*?(?=/\* MEMEFLOW LOADER FINAL|\Z)',
]
for pat in patterns:
    css = re.sub(pat, '', css, flags=re.S)

# Remove old V6 loader rules if present.
start = css.find(".boot-mark{")
light = css.find('html[data-theme="light"]')
if start != -1 and light != -1 and start < light:
    segment = css[start:light]
    if ".mf-loader" in segment and ".mf-loader-v9" not in segment:
        css = css[:start] + css[light:]

cssp.write_text(css.rstrip() + "\n", encoding="utf-8")
PY

cat >> "$APP/memeflow-brand.css" <<'MFV9CSS'

/* MEMEFLOW LOADER FINAL V9 — pinned wing roots, clean mobile loader */
.boot-mark{
  width:144px!important;
  height:112px!important;
  min-width:144px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  border:0!important;
  border-radius:0!important;
  background:none!important;
  box-shadow:none!important;
  overflow:visible!important;
}
.boot-mark>i,.boot-mark::before,.boot-mark::after{
  display:none!important;
  content:none!important;
}

.mf-loader-v9{
  position:relative;
  width:140px;
  height:108px;
  display:block;
  overflow:visible;
  transform:translateZ(0);
  filter:drop-shadow(0 8px 20px rgba(0,225,240,.24));
  animation:mfV9Float 1.9s ease-in-out infinite;
}
.mf-loader-v9 img{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:contain;
  pointer-events:none;
  will-change:transform,opacity,filter;
}
.mf-loader-v9 .mf-v9-glow{
  z-index:1;
  animation:mfV9Glow 1.2s ease-in-out infinite alternate;
}
.mf-loader-v9 .mf-v9-ul{
  z-index:2;
  transform-origin:46.2% 40.6%;
  animation:mfV9UL .64s cubic-bezier(.42,0,.58,1) infinite alternate;
}
.mf-loader-v9 .mf-v9-ur{
  z-index:2;
  transform-origin:53.8% 40.6%;
  animation:mfV9UR .64s cubic-bezier(.42,0,.58,1) infinite alternate;
}
.mf-loader-v9 .mf-v9-ll{
  z-index:3;
  transform-origin:46.2% 42.8%;
  animation:mfV9LL .78s cubic-bezier(.42,0,.58,1) .08s infinite alternate;
}
.mf-loader-v9 .mf-v9-lr{
  z-index:3;
  transform-origin:53.8% 42.8%;
  animation:mfV9LR .78s cubic-bezier(.42,0,.58,1) .08s infinite alternate;
}
.mf-loader-v9 .mf-v9-body{
  z-index:5;
  animation:mfV9Body 1.45s ease-in-out infinite;
}

/* Roots stay pinned; motion comes mainly from wing foreshortening. */
@keyframes mfV9UL{
  0%{transform:scaleY(.72) rotate(-1.2deg);opacity:.82}
  100%{transform:scaleY(1.03) rotate(.8deg);opacity:1}
}
@keyframes mfV9UR{
  0%{transform:scaleY(.72) rotate(1.2deg);opacity:.82}
  100%{transform:scaleY(1.03) rotate(-.8deg);opacity:1}
}
@keyframes mfV9LL{
  0%{transform:scaleY(.83) rotate(-.7deg);opacity:.78}
  100%{transform:scaleY(1.015) rotate(.5deg);opacity:.96}
}
@keyframes mfV9LR{
  0%{transform:scaleY(.83) rotate(.7deg);opacity:.78}
  100%{transform:scaleY(1.015) rotate(-.5deg);opacity:.96}
}
@keyframes mfV9Glow{
  from{opacity:.22;transform:scale(.97)}
  to{opacity:.60;transform:scale(1.045)}
}
@keyframes mfV9Body{
  0%,100%{filter:brightness(.98)}
  50%{filter:brightness(1.10)}
}
@keyframes mfV9Float{
  0%,100%{transform:translateY(2px)}
  50%{transform:translateY(-3px)}
}

@media (prefers-reduced-motion:reduce){
  .mf-loader-v9{animation:mfV9Float 2.8s ease-in-out infinite!important}
  .mf-loader-v9 .mf-v9-ul,.mf-loader-v9 .mf-v9-ur{animation-duration:1.2s!important}
  .mf-loader-v9 .mf-v9-ll,.mf-loader-v9 .mf-v9-lr{animation-duration:1.4s!important}
}

MFV9CSS

python3 <<'PY'
import os, re
from pathlib import Path

app = Path(os.environ["APP"])
p = app / "system.html"
if not p.exists():
    raise SystemExit("ERROR: system.html not found")

text = p.read_text(encoding="utf-8")

loader = (
    '<div class="boot-mark"><span class="mf-loader-v9">'
    '<img class="mf-v9-glow" src="/brand/loader-v9/glow.png?v=v9" alt="">'
    '<img class="mf-v9-ul" src="/brand/loader-v9/wing-upper-left.png?v=v9" alt="">'
    '<img class="mf-v9-ur" src="/brand/loader-v9/wing-upper-right.png?v=v9" alt="">'
    '<img class="mf-v9-ll" src="/brand/loader-v9/wing-lower-left.png?v=v9" alt="">'
    '<img class="mf-v9-lr" src="/brand/loader-v9/wing-lower-right.png?v=v9" alt="">'
    '<img class="mf-v9-body" src="/brand/loader-v9/body.png?v=v9" alt="">'
    '</span></div>'
)

text, n = re.subn(
    r'<div\s+class="boot-mark"[^>]*>.*?</div>',
    loader,
    text,
    count=1,
    flags=re.S
)
if n != 1:
    raise SystemExit("ERROR: boot-mark not found in system.html")

# Force Safari to fetch the new CSS.
text = re.sub(
    r'/memeflow-brand\.css\?v=[^"\']+',
    '/memeflow-brand.css?v=loader-v9',
    text
)

p.write_text(text, encoding="utf-8")
PY

echo
echo "[MEMEFLOW] HTTP check"
for u in \
  /brand/loader-v9/wing-upper-left.png \
  /brand/loader-v9/wing-upper-right.png \
  /brand/loader-v9/wing-lower-left.png \
  /brand/loader-v9/wing-lower-right.png \
  /brand/loader-v9/body.png \
  /brand/loader-v9/glow.png \
  /memeflow-brand.css \
  /system.html
do
  code="$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3000$u" || true)"
  echo "  $u -> $code"
done

echo
echo "✅ APPROVED MEMEFLOW LOADER V9 INSTALLED LOCALLY"
echo "No commit or push was performed."
echo
echo "Open:"
echo "  /system.html?v=loader-v9"
